"""Operator commands: durable progress, bounded scheduling and explicit recovery."""

import argparse
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
import json
from pathlib import Path
import sys
import time

from .exports import read_export
from .mock_provider import MockProvider
from .provider import AnthropicProvider, ProviderConfig
from .review import intake
from .storage import Store, processing_settings


def positive(value):
    value = int(value)
    if value < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return value


def parser():
    result = argparse.ArgumentParser(description="Prepare IT access requests for human review")
    result.add_argument("--db", default=".access-requests/state.sqlite3")
    result.add_argument("--mock-config", type=Path)
    result.add_argument("--model", default="claude-sonnet-5-5")
    result.add_argument("--endpoint", default="https://api.anthropic.com/v1/messages")
    result.add_argument("--max-tokens", type=positive, default=8192)
    result.add_argument("--timeout", type=float, default=60)
    result.add_argument("--prompt", type=Path)
    result.add_argument("--schema", type=Path)
    result.add_argument("--policy", type=Path)
    commands = result.add_subparsers(dest="command", required=True)
    for name in ("intake", "resume", "retry"):
        command = commands.add_parser(name)
        if name == "intake":
            command.add_argument("source", type=Path)
        if name == "retry":
            command.add_argument("--document", required=True)
            command.add_argument("--source", type=Path)
        command.add_argument("--workers", type=positive, default=4)
        command.add_argument("--attempts", type=positive, default=1)
        command.add_argument("--backoff", type=float, default=1)
        command.add_argument("--max-backoff", type=float, default=30)
    commands.add_parser("queue")
    commands.add_parser("pending")
    history = commands.add_parser("history")
    history.add_argument("--document")
    export = commands.add_parser("export")
    export.add_argument("destination", type=Path)
    return result


def make_provider(args):
    if args.mock_config:
        config = json.loads(args.mock_config.read_text(encoding="utf-8"))
        directory = args.mock_config.parent / config.get("fixtures_dir", ".")
        provider = MockProvider(directory, replies=config.get("replies"), scripts=config.get("scripts"))
        # Controls (delay/error sequences) are simulated transport behavior, not
        # request configuration. The saved configuration is retained for audit.
        provider.mock_config_path = str(args.mock_config.resolve())
    else:
        provider = AnthropicProvider(ProviderConfig(endpoint=args.endpoint, model=args.model,
                                     max_tokens=args.max_tokens, timeout=args.timeout),
                                     prompt_path=args.prompt, schema_path=args.schema, policy_path=args.policy)
    for attribute, path in (("prompt_path", args.prompt), ("schema_path", args.schema), ("policy_path", args.policy)):
        if path:
            setattr(provider, attribute, path)
    return provider


def execute_attempt(store, attempt, provider, args):
    try:
        for index in range(args.attempts):
            result, = intake([attempt.document], provider)
            result = store.complete(attempt, result)
            if (result.get("error_kind") not in ("timeout", "unavailable", "rate_limit")
                    or index + 1 == args.attempts):
                return result
            current = next(r for r in store.current() if r["document_id"] == result["document_id"])
            if current["attempt_id"] != result["attempt_id"]:
                return result
            delay = min(args.max_backoff, max(args.backoff * (2 ** index), result.get("retry_after_seconds", 0)))
            time.sleep(max(0, delay))
            attempt = store.begin(attempt.document, processing_settings(provider), retry=True)
        return result
    finally:
        attempt.close()


def schedule(store, attempts, provider, args):
    """Bound submitted futures to worker count; provider waits hold no DB lock."""
    results = [attempt.record for attempt in attempts if attempt.reused]
    iterator = iter(attempt for attempt in attempts if not attempt.reused)
    try:
        with ThreadPoolExecutor(max_workers=args.workers) as pool:
            active = set()
            for _ in range(args.workers):
                attempt = next(iterator, None)
                if attempt is not None:
                    active.add(pool.submit(execute_attempt, store, attempt, provider, args))
            while active:
                done, active = wait(active, return_when=FIRST_COMPLETED)
                for future in done:
                    results.append(future.result())
                    attempt = next(iterator, None)
                    if attempt is not None:
                        active.add(pool.submit(execute_attempt, store, attempt, provider, args))
    finally:
        for attempt in attempts:
            attempt.close()
    return sorted(results, key=lambda record: (record["document_id"], record["attempt_id"]))


def main(argv=None):
    args = parser().parse_args(argv)
    try:
        store = Store(args.db)
        if args.command == "queue":
            output = store.current()
        elif args.command == "history":
            output = store.history(args.document)
        elif args.command == "pending":
            output = store.pending()
        elif args.command == "export":
            output = {"generation": str(store.export(args.destination))}
        else:
            if args.timeout <= 0 or args.backoff < 0 or args.max_backoff < 0:
                raise ValueError("Timeout must be positive; backoff values must be nonnegative")
            provider = make_provider(args)
            settings = processing_settings(provider)
            attempts = []
            if args.command == "intake":
                paths = [args.source] if args.source.is_file() else sorted(args.source.glob("*.json"))
                if not paths:
                    raise ValueError("No JSON source exports found")
                # Validate input before acquiring any durable attempt ownership.
                documents = [read_export(path) for path in paths]
                attempts = [store.begin(document, settings) for document in documents]
            elif args.command == "retry":
                if args.source:
                    document = read_export(args.source)
                    if document.document_id != args.document:
                        raise ValueError("Retry source filename must match --document")
                else:
                    with store.connection() as db:
                        row = db.execute("SELECT raw FROM attempts WHERE document_id=? ORDER BY id DESC LIMIT 1",
                                         (args.document,)).fetchone()
                    if row is None:
                        raise ValueError("Document is unknown; provide --source")
                    raw = row["raw"]
                    from .exports import SourceDocument
                    import hashlib
                    export = json.loads(raw.decode("utf-8"))
                    document = SourceDocument(args.document, raw, hashlib.sha256(raw).hexdigest(), export["message"],
                                              {k: v for k, v in export.items() if k != "message"})
                attempts = [store.begin(document, settings, retry=True)]
            else:
                for record in store.pending():
                    attempt = store.claim(record["attempt_id"])
                    if attempt is None:
                        continue
                    if attempt.settings != settings:
                        attempt.close()
                        raise ValueError("Pending settings differ; resume with original settings or explicitly retry the document")
                    attempts.append(attempt)
            output = schedule(store, attempts, provider, args)
        print(json.dumps(output, indent=2))
        return int(isinstance(output, list) and any(row.get("status") == "error" for row in output)
                   and args.command in ("intake", "resume", "retry"))
    except (ValueError, OSError, KeyError) as exc:
        print(f"access-requests: {exc}", file=sys.stderr)
        return 2

"""Source-grounded scalar evaluation using the human-approved, frozen D5 rules."""

import hashlib
import json
from pathlib import Path

from .validation import validate_extraction


def score_records(records, expected, documents, rules):
    fields = rules["fields"]
    if len(expected) != rules["documents"] or len(fields) * len(expected) != rules["denominator"]:
        raise ValueError("Frozen document/field counts do not match the denominator")
    indexed = {}
    for record in records:
        name = record["document_id"]
        if name in indexed:
            raise ValueError(f"duplicate document_id: {name}")
        indexed[name] = record
    errors, routing_errors, evidence_errors = [], [], []
    matched = 0
    for name, expectation in expected.items():
        if name not in documents or expectation["source_sha256"] != documents[name].source_sha256:
            raise ValueError(f"Expected source identity does not match: {name}")
        if set(expectation["facts"]) != set(fields):
            raise ValueError(f"Incomplete frozen facts: {name}")
        message = documents[name].message
        for quote in expectation["evidence"]:
            if not quote or quote not in message:
                raise ValueError(f"Invented expected evidence: {name}")
        record = indexed.get(name)
        reason = None
        extraction = None
        if record is None:
            reason = "missing document"
        elif record.get("status") not in ("review", "needs-information") or record.get("error") is not None:
            reason = "failed or unfinished extraction"
        elif record.get("source_sha256") != expectation["source_sha256"]:
            reason = "source identity mismatch"
        else:
            extraction = record.get("extraction")
            try:
                validate_extraction(extraction, message)
            except ValueError:
                reason = "invalid extraction"
        for field in fields:
            target = expectation["facts"][field]
            actual = extraction.get(field) if isinstance(extraction, dict) else None
            if reason is None and field in extraction and actual == target:
                matched += 1
            else:
                errors.append({"document_id": name, "field": field, "expected": target,
                               "actual": actual, "reason": reason or "value mismatch"})
        if record:
            for field, value in expectation["route"].items():
                if record.get(field) != value:
                    routing_errors.append({"document_id": name, "field": field,
                                           "expected": value, "actual": record.get(field)})
        if isinstance(extraction, dict):
            quotes = extraction.get("supporting_quotes", [])
            if not isinstance(quotes, list) or not all(isinstance(quote, str) for quote in quotes):
                quotes = []
            for quote in expectation["evidence"]:
                if not any(quote in supplied for supplied in quotes):
                    evidence_errors.append({"document_id": name, "missing_evidence": quote})
    total = rules["denominator"]
    configs = {json.dumps(record.get("provider_config", {}), sort_keys=True) for record in records}
    return {
        "matched": matched, "total": total, "accuracy": matched / total,
        "factual_errors": errors, "routing_errors": routing_errors, "evidence_errors": evidence_errors,
        "unexpected_documents": sorted(set(indexed) - set(expected)),
        "response_sources": sorted({record.get("response_source", "unknown") for record in records}),
        "provider_configurations": [json.loads(config) for config in sorted(configs)],
    }


def write_report(path, report, expected, expected_path, rules_path):
    expected_hash = hashlib.sha256(Path(expected_path).read_bytes()).hexdigest()
    rules_hash = hashlib.sha256(Path(rules_path).read_bytes()).hexdigest()
    lines = [
        "# Source-grounded accuracy evaluation", "",
        "Observed configuration: saved mock responses from `tests/mock_responses/evaluation-config.json`.",
        "These observations exercise fixture plumbing and deterministic policy, not live model accuracy.",
        "The Anthropic HTTP adapter is separately contract-tested through fake transport; no live call was made.", "",
        "Rules approved by the user and frozen before scoring: 12 scalar fields × 21 messages = 252 comparisons.",
        "Strings compare exactly, including case and whitespace. Dates have no additional normalization.",
        "A successful explicit null matches only an expected null. Missing documents and failed, unfinished,",
        "source-mismatched or schema-invalid records receive zero of 12 matches, even for expected nulls.",
        "Unexpected documents are reported separately; they do not change the denominator. Routing and",
        "evidence checks are separate and do not increase the accuracy denominator.", "",
        f"Observed scalar matches: **{report['matched']}/{report['total']} ({report['accuracy']:.2%})**.",
        f"Factual errors: {len(report['factual_errors'])}; routing differences: {len(report['routing_errors'])}; "
        f"evidence differences: {len(report['evidence_errors'])}.",
        f"Unexpected documents: {json.dumps(report['unexpected_documents'])}.", "",
        f"Frozen expectation SHA-256: `{expected_hash}`.", f"Frozen rules SHA-256: `{rules_hash}`.", "",
        "Reproduce from the repository root after mocked intake of the corpus and paraphrase:", "",
        "```bash", "env -u API_KEY python3 -m access_requests accuracy --records deliverables/extractions.jsonl --report deliverables/accuracy.md", "```", "",
        "Expected fields below were transferred from the independent F001–F021 source ledger before scorer",
        "implementation. [expected-fields.json](expected-fields.json) contains every exact evidence quote,",
        "source hash and expected route. [accuracy-rules.json](accuracy-rules.json) contains the frozen rules.",
        "Null expectations reflect review of the full source and policy; a short quote alone cannot prove absence.", "",
        "| Document | Expected scalar facts |", "|---|---|",
    ]
    for name, expectation in expected.items():
        facts = "; ".join(f"`{field}={json.dumps(value, ensure_ascii=False)}`"
                          for field, value in expectation["facts"].items())
        lines.append(f"| {name} | {facts} |")
    lines += ["", "Detailed observations and factual differences:", "", "```json",
              json.dumps(report, indent=2), "```", "",
              "The hand-authored mocks encode known facts. Their match rate does not establish extraction",
              "quality on fresh live responses, generalization, provider latency or throughput.", ""]
    Path(path).write_text("\n".join(lines), encoding="utf-8")

